class CustomArray {
    private var array: [Int]

    init(size: Int) {
        array = Array(repeating: 0, count: size)
    }

    func set(index: Int, value: Int) {
        guard index >= 0 && index < array.count else {
            fatalError("Index out of bounds")
        }
        array[index] = value
    }

    func get(index: Int) -> Int {
        guard index >= 0 && index < array.count else {
            fatalError("Index out of bounds")
        }
        return array[index]
    }
}
```

